import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {InputComponent} from "./input.component";
import {PI_INPUT_ACTION, PI_INPUT_CARD} from "./input.types";

export * from "./input.types";

registerCardComponent({
  name: PI_INPUT_CARD,
  component: InputComponent,
  events: actionTypesToEvents(PI_INPUT_ACTION),
});

import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Input} from "@/components/ui/input";
import {Label} from "@/components/ui/label";
import {useFormContext} from "@/cards/form/form.context";
import type {PiInputEvents, PiInputProps} from "./input.types";

export const InputComponent = (
  props: PiCardProps<PiInputProps, PiInputEvents>,
): React.ReactNode => {
  const {
    name,
    value: propValue = "",
    type = "text",
    placeholder,
    disabled,
    label,
    description,
    className,
    cardName,
    onChanged,
    onCommitted,
  } = props;

  // `id` and `invalid` may be injected by a parent pi/field card via
  // Pihanga's extra-prop forwarding.  They are not in the official type so
  // we read them through an escape hatch.
  const injectedId = (props as {id?: string}).id;
  const invalid = Boolean((props as {invalid?: boolean}).invalid);

  // Detect if we are inside a pi/form card via React context.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  // Local display state — lets the user type freely without triggering Redux
  // on every keystroke.  Only `onCommitted` (blur / Enter) writes back to
  // Redux, so callers that use `onCommitted` instead of `onChanged` avoid
  // per-keystroke panel rebuilds.
  const [localValue, setLocalValue] = React.useState<string>(
    type === "file" ? "" : propValue,
  );

  // Sync local value when the prop changes from outside (e.g. when a different
  // card is selected in the playground, resetting the controls panel).
  React.useEffect(() => {
    if (!useFormData && type !== "file") {
      setLocalValue(propValue);
    }
  }, [propValue, useFormData, type]);

  // Derive the effective value for the controlled <Input>:
  //   - inside a form → read from form.formData[name]
  //   - standalone   → use localValue (updated on every keystroke locally)
  //   - file inputs  → uncontrolled (no value binding)
  const inputValue =
    type === "file"
      ? undefined
      : useFormData
        ? ((form.formData[name!] as string | undefined) ?? "")
        : localValue;

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const newValue =
      type === "file" ? (e.target.files?.[0]?.name ?? "") : e.target.value;
    if (useFormData) {
      form.handleChange(name!, newValue);
    } else {
      setLocalValue(newValue);
      onChanged({name, value: newValue});
    }
  }

  // Fire onCommitted when the user leaves the field or presses Enter.
  function handleBlur() {
    if (!useFormData && type !== "file") {
      onCommitted({name, value: localValue});
    }
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter" && !useFormData && type !== "file") {
      onCommitted({name, value: localValue});
    }
  }

  // Use the id injected by pi/field (for label↔control linking); fall back
  // to a locally-generated id when used standalone.
  const selfId = `${cardName}-${name ?? "input"}`;
  const fieldId = injectedId ?? selfId;

  return (
    <div data-pihanga={cardName} className="grid w-full gap-1.5">
      {label && <Label htmlFor={fieldId}>{label}</Label>}
      <Input
        id={fieldId}
        type={type}
        value={inputValue}
        onChange={handleChange}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        disabled={disabled}
        className={className}
        aria-invalid={invalid || undefined}
        aria-describedby={description ? `${fieldId}-desc` : undefined}
      />
      {description && (
        <p id={`${fieldId}-desc`} className="text-sm text-muted-foreground">
          {description}
        </p>
      )}
    </div>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PI_INPUT_CARD = "pi/input";

export const PiInput = createCardDeclaration<PiInputProps, PiInputEvents>(
  PI_INPUT_CARD,
);

export const PI_INPUT_ACTION = registerActions(PI_INPUT_CARD, [
  "changed",
  "committed",
]);

export const onInputChanged = createOnAction<PiInputChangedEvent>(
  PI_INPUT_ACTION.CHANGED,
);

/** @deprecated Use `onInputChanged` instead. */
export const onPiInputChanged = onInputChanged;

/**
 * Subscribe to "committed" events — fired when the user finishes editing
 * (blur or Enter key).  Unlike `onInputChanged` (which fires on every keystroke),
 * `onInputCommitted` only fires once per editing session, making it the preferred
 * handler for controlled inputs that trigger expensive downstream work.
 */
export const onInputCommitted = createOnAction<PiInputCommittedEvent>(
  PI_INPUT_ACTION.COMMITTED,
);

/** @deprecated Use `onInputCommitted` instead. */
export const onPiInputCommitted = onInputCommitted;

// ---------------------------------------------------------------------------
// Props & Events
// ---------------------------------------------------------------------------

export type PiInputProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its value from form state and writes
   * back via form.handleChange.
   */
  name?: string;

  /**
   * Controlled value used in standalone mode (outside a Form).
   * Ignored when `name` is set and the component is inside a pi/form.
   */
  value?: string;

  /**
   * HTML input type.
   * Common values: "text" | "email" | "password" | "number" | "search" |
   * "url" | "tel" | "date" | "file".
   * Defaults to "text".
   */
  type?: string;

  /** Placeholder text shown when the input is empty. */
  placeholder?: string;

  /** When true, the input is disabled and non-interactive. */
  disabled?: boolean;

  /**
   * Optional label text rendered in a `<label>` element above the input.
   * The label is automatically associated with the input via `htmlFor`.
   */
  label?: string;

  /**
   * Optional helper / description text rendered below the input.
   * Use this for hints, formatting guidance, or validation feedback.
   */
  description?: string;

  /** Extra Tailwind / CSS classes forwarded to the underlying <input> element. */
  className?: string;
};

export type PiInputChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** New value after the change. */
  value: string;
};

/**
 * Payload for the `onCommitted` event (blur / Enter key).
 * Same shape as `PiInputChangedEvent`.
 */
export type PiInputCommittedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** Final committed value. */
  value: string;
};

export type PiInputEvents = {
  /** Fires on every keystroke. */
  onChanged: PiInputChangedEvent;
  /**
   * Fires once when the user finishes editing (blur or Enter key).
   * Use this instead of `onChanged` when each change triggers expensive
   * downstream work (e.g. rebuilding a panel).
   */
  onCommitted: PiInputCommittedEvent;
};
